import os
import uuid
from flask import Flask, render_template, request, jsonify, send_from_directory
from services.db import db, init_db
from services.models import FeedIngredient, AnimalRequirement, FeedFormula, LedgerEntry, IdempotencyKey
from services.formulator_service import solve_feed_formulation
from services.pos_service import process_pos_transaction
from services.ledger_service import record_idempotent_transaction

app = Flask(__name__)
app.config['SECRET_KEY'] = os.getenv('SECRET_KEY', 'emining-erp-pwa-secret-key-2026')
app.config['SQLALCHEMY_DATABASE_URI'] = os.getenv('DATABASE_URL', 'sqlite:///emining_erp.db')
app.config['SQLALCHEMY_TRACK_MODIFICATIONS'] = False

init_db(app)

@app.route('/')
def dashboard():
    return render_template('dashboard.html')

@app.route('/manifest.json')
def serve_manifest():
    return send_from_directory('static', 'manifest.json')

@app.route('/sw.js')
def serve_sw():
    return send_from_directory('static', 'sw.js', mimetype='application/javascript')

@app.route('/api/formulate', methods=['POST'])
def api_formulate():
    data = request.get_json() or {}
    target_species = data.get('species')
    target_weight = float(data.get('target_batch_kg', 1000.0))
    selected_ingredients = data.get('ingredients', [])

    result = solve_feed_formulation(target_species, target_weight, selected_ingredients)
    return jsonify(result)

@app.route('/api/pos/checkout', methods=['POST'])
def api_pos_checkout():
    data = request.get_json() or {}
    idempotency_key = request.headers.get('X-Idempotency-Key') or str(uuid.uuid4())

    # Verify Idempotency
    existing_key = IdempotencyKey.query.filter_by(key=idempotency_key).first()
    if existing_key:
        return jsonify({"status": "already_processed", "response": existing_key.response_json}), 200

    try:
        transaction_result = process_pos_transaction(data)

        # Record Idempotent Ledger Entry
        ledger_res = record_idempotent_transaction(
            account_id=data.get('customer_id', 'WALK_IN'),
            amount=data.get('total_amount', 0.0),
            idempotency_key=idempotency_key,
            description=f"POS Feed Sale Batch {data.get('batch_id', 'N/A')}"
        )

        response_payload = {
            "status": "success",
            "transaction": transaction_result,
            "ledger": ledger_res
        }

        new_key = IdempotencyKey(key=idempotency_key, response_json=response_payload)
        db.session.add(new_key)
        db.session.commit()

        return jsonify(response_payload), 200

    except Exception as e:
        db.session.rollback()
        return jsonify({"status": "error", "message": str(e)}), 400

@app.route('/api/sync/outbox', methods=['POST'])
def api_sync_outbox():
    payloads = request.get_json() or []
    processed = []
    errors = []

    for item in payloads:
        action_type = item.get('type')
        data = item.get('data')
        key = item.get('idempotency_key')

        if action_type == 'POS_CHECKOUT':
            try:
                # Reuse checkout logic idempotently
                existing_key = IdempotencyKey.query.filter_by(key=key).first()
                if not existing_key:
                    tx_res = process_pos_transaction(data)
                    ld_res = record_idempotent_transaction(
                        account_id=data.get('customer_id', 'OFFLINE_WALK_IN'),
                        amount=data.get('total_amount', 0.0),
                        idempotency_key=key,
                        description="Offline Queue POS Sync"
                    )
                    res_payload = {"status": "success", "transaction": tx_res, "ledger": ld_res}
                    db.session.add(IdempotencyKey(key=key, response_json=res_payload))
                    db.session.commit()
                processed.append(item.get('queue_id'))
            except Exception as ex:
                errors.append({"queue_id": item.get('queue_id'), "error": str(ex)})

    return jsonify({"synced_ids": processed, "errors": errors}), 200

if __name__ == '__main__':
    app.run(host='0.0.0.0', port=5000, debug=True)

from flask_sqlalchemy import SQLAlchemy
db = SQLAlchemy()
def init_db(app): db.init_app(app) with app.app_context(): db.create_all()

from services.db import db from services.models import FeedIngredient
def process_pos_transaction(data): cart_items = data.get('cart', []) updated_items = [] total_bill = 0.0
for item in cart_items: ing_id = item.get('ingredient_id') qty_kg = float(item.get('qty_kg', 0.0))
ingredient = FeedIngredient.query.get(ing_id) if not ingredient: raise Exception(f"Ingredient ID {ing_id} not found.")
if ingredient.stock_quantity_kg < qty_kg: raise Exception(f"Insufficient stock for {ingredient.name}. Available: {ingredient.stock_quantity_kg}kg, Requested: {qty_kg}kg")
ingredient.stock_quantity_kg -= qty_kg subtotal = qty_kg * ingredient.cost_per_kg total_bill += subtotal
updated_items.append({ "ingredient_id": ingredient.id, "name": ingredient.name, "qty_kg": qty_kg, "unit_price": ingredient.cost_per_kg, "subtotal": subtotal, "remaining_stock_kg": ingredient.stock_quantity_kg })
db.session.commit() return { "customer_id": data.get('customer_id', 'WALK_IN'), "total_amount": round(total_bill, 2), "items": updated_items }

from services.db import db from services.models import LedgerEntry
def record_idempotent_transaction(account_id, amount, idempotency_key, description=""): existing_entry = LedgerEntry.query.filter_by(idempotency_key=idempotency_key).first() if existing_entry: return { "status": "duplicate_prevented", "ledger_id": existing_entry.id, "account_id": existing_entry.account_id, "amount": existing_entry.amount, "timestamp": existing_entry.timestamp.isoformat() }
entry = LedgerEntry( account_id=account_id, amount=amount, idempotency_key=idempotency_key, description=description ) db.session.add(entry) db.session.commit()
return { "status": "recorded", "ledger_id": entry.id, "account_id": entry.account_id, "amount": entry.amount, "timestamp": entry.timestamp.isoformat() }


const CACHE_NAME = 'emining-erp-v1';
const ASSETS = [
  '/',
  '/static/manifest.json',
  '/static/css/adminlte.min.css',
  '/static/js/outbox.js',
  '/static/js/app.js'
];

self.addEventListener('install', (event) => {
  event.waitUntil(
    caches.open(CACHE_NAME).then((cache) => {
      return cache.addAll(ASSETS);
    })
  );
  self.skipWaiting();
});

self.addEventListener('activate', (event) => {
  event.waitUntil(
    caches.keys().then((keys) => {
      return Promise.all(
        keys.map((key) => {
          if (key !== CACHE_NAME) {
            return caches.delete(key);
          }
        })
      );
    })
  );
  self.clients.claim();
});

self.addEventListener('fetch', (event) => {
  if (event.request.method === 'GET') {
    event.respondWith(
      caches.match(event.request).then((cachedResponse) => {
        if (cachedResponse) {
          fetch(event.request).then((networkResponse) => {
            if (networkResponse.status === 200) {
              caches.open(CACHE_NAME).then((cache) => cache.put(event.request, networkResponse));
            }
          }).catch(() => {});
          return cachedResponse;
        }
        return fetch(event.request);
      })
    );
  }
});

self.addEventListener('sync', (event) => {
  if (event.tag === 'sync-outbox-queue') {
    event.waitUntil(self.triggerOutboxSync());
  }
});

self.triggerOutboxSync = async () => {
  const allClients = await clients.matchAll();
  for (const client of allClients) {
    client.postMessage({ action: 'TRIGGER_SYNC' });
  }
};


class OutboxManager {
  constructor() {
    this.dbName = 'EminingOutboxDB';
    this.dbVersion = 1;
    this.db = null;
    this.initDB();
  }

  initDB() {
    return new Promise((resolve, reject) => {
      const request = indexedDB.open(this.dbName, this.dbVersion);
      request.onupgradeneeded = (event) => {
        const db = event.target.result;
        if (!db.objectStoreNames.contains('outbox')) {
          db.createObjectStore('outbox', { keyPath: 'queue_id', autoIncrement: true });
        }
      };
      request.onsuccess = (event) => {
        this.db = event.target.result;
        resolve(this.db);
      };
      request.onerror = (event) => reject(event.target.error);
    });
  }

  async enqueue(type, data) {
    if (!this.db) await this.initDB();
    const idempotency_key = 'idemp-' + Date.now() + '-' + Math.random().toString(36).substr(2, 9);
    const item = { type, data, idempotency_key, created_at: new Date().toISOString() };

    return new Promise((resolve, reject) => {
      const tx = this.db.transaction('outbox', 'readwrite');
      const store = tx.objectStore('outbox');
      const req = store.add(item);
      req.onsuccess = () => {
        if ('serviceWorker' in navigator && 'SyncManager' in window) {
          navigator.serviceWorker.ready.then((swRegistration) => {
            swRegistration.sync.register('sync-outbox-queue');
          });
        }
        resolve(item);
      };
      req.onerror = (e) => reject(e.target.error);
    });
  }

  async getAll() {
    if (!this.db) await this.initDB();
    return new Promise((resolve, reject) => {
      const tx = this.db.transaction('outbox', 'readonly');
      const store = tx.objectStore('outbox');
      const req = store.getAll();
      req.onsuccess = () => resolve(req.result);
      req.onerror = (e) => reject(e.target.error);
    });
  }

  async remove(queue_id) {
    if (!this.db) await this.initDB();
    return new Promise((resolve, reject) => {
      const tx = this.db.transaction('outbox', 'readwrite');
      const store = tx.objectStore('outbox');
      const req = store.delete(queue_id);
      req.onsuccess = () => resolve();
      req.onerror = (e) => reject(e.target.error);
    });
  }

  async flushOutbox() {
    const queue = await this.getAll();
    if (queue.length === 0) return;

    try {
      const response = await fetch('/api/sync/outbox', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify(queue)
      });
      const resData = await response.json();
      if (resData.synced_ids) {
        for (const id of resData.synced_ids) {
          await this.remove(id);
        }
      }
    } catch (err) {
      console.log('Outbox flush deferred: offline mode active.');
    }
  }
}

window.outboxManager = new OutboxManager();

window.addEventListener('online', () => {
  window.outboxManager.flushOutbox();
});

if ('serviceWorker' in navigator) {
  navigator.serviceWorker.addEventListener('message', (event) => {
    if (event.data && event.data.action === 'TRIGGER_SYNC') {
      window.outboxManager.flushOutbox();
    }
  });
}


{% extends "base.html" %}
{% block content %}
<div class="card">
  <h3>EMINING ERP Control Center</h3>
  <p>System unified across InvenTree, Frappe, Flask-POS, Linear Formulation, Outbox PWA, & Stripe Idempotent Ledger.</p>
</div>

<div class="card">
  <h4>Feed Ration Optimization Engine</h4>
  <label>Target Species/Stage:</label>
  <select id="species-select">
    <option value="Dairy_High_Yield">Dairy Cattle (High Yield 15L+)</option>
    <option value="Poultry_Broiler_Starter">Poultry Broiler Starter</option>
    <option value="Pig_Grower">Pig Grower Rations</option>
  </select>
  <br/><br/>
  <label>Batch Size (KG):</label>
  <input type="number" id="batch-kg" value="1000"/>
  <br/><br/>
  <button onclick="runFormulation()">Calculate Matrix Formulation</button>
  <pre id="formulation-result" style="background:#f8f9fa; padding:10px; margin-top:15px; border-radius:4px;"></pre>
</div>

<div class="card">
  <h4>Offline-Capable Point of Sale (POS) Checkout</h4>
  <p>Transactions created while offline are auto-queued in the IndexedDB Outbox and synced upon reconnection.</p>
  <button onclick="executeCheckout()">Process Sample POS Transaction</button>
  <pre id="pos-result" style="background:#f8f9fa; padding:10px; margin-top:15px; border-radius:4px;"></pre>
</div>

<script>
  async function runFormulation() {
    const species = document.getElementById('species-select').value;
    const target_batch_kg = document.getElementById('batch-kg').value;
    const res = await fetch('/api/formulate', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ species, target_batch_kg })
    });
    const data = await res.json();
    document.getElementById('formulation-result').textContent = JSON.stringify(data, null, 2);
  }

  async function executeCheckout() {
    const cartData = {
      customer_id: "CUST-KABARNET-001",
      total_amount: 4500.00,
      cart: [{ ingredient_id: 1, qty_kg: 50.0 }]
    };

    if (navigator.onLine) {
      try {
        const res = await fetch('/api/pos/checkout', {
          method: 'POST',
          headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify(cartData)
        });
        const data = await res.json();
        document.getElementById('pos-result').textContent = "Online Checkout Successful:\n" + JSON.stringify(data, null, 2);
      } catch (err) {
        queueOffline(cartData);
      }
    } else {
      queueOffline(cartData);
    }
  }

  async function queueOffline(cartData) {
    await window.outboxManager.enqueue('POS_CHECKOUT', cartData);
    document.getElementById('pos-result').textContent = "OFFLINE DETECTED: Transaction safely queued in IndexedDB Outbox. Will auto-sync when online.";
  }
</script>
{% endblock %}
